export interface ConnectorConfig {
  /** Airtable personal access token (from env var AIRTABLE_PERSONAL_ACCESS_TOKEN) */
  airtablePersonalAccessToken: string;
  /** Full Discord incoming webhook URL (e.g. https://discord.com/api/webhooks/{id}/{token}) */
  discordWebhookUrl: string;
  /** Optional fetch implementation (defaults to global fetch) */
  fetch?: typeof fetch;
}

/** Input payload as delivered by the Airtable new-record webhook */
export interface AirtableWebhookPayload {
  payloads: Array<{
    id: string;
    baseId: string;
    tableId: string;
    webhookId: string;
    timestamp: string;
    baseTransactionNumber: number;
    changedTablesById: Record<string, {
      recordIds: string[];
      cellValuesByFieldId: Record<string, unknown>;
      changedFieldsByRecordId: Record<string, unknown>;
    }>;
  }>;
}

interface AirtableRecord {
  id: string;
  fields: Record<string, unknown>;
  createdTime: string;
}

export interface HandleResult {
  messageIds: string[];
}

export async function handle(
  payload: AirtableWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new Error('No fetch implementation available');
  }

  if (!payload.payloads || !Array.isArray(payload.payloads)) {
    throw new Error('Payload must contain a "payloads" array');
  }

  const messageIds: string[] = [];

  for (const p of payload.payloads) {
    if (!p.baseId) throw new Error('Payload missing baseId');
    if (!p.tableId) throw new Error('Payload missing tableId');
    if (!p.changedTablesById) throw new Error('Payload missing changedTablesById');

    const tableData = p.changedTablesById[p.tableId];
    if (!tableData) {
      throw new Error(`Payload missing changedTablesById for table ${p.tableId}`);
    }
    if (!tableData.recordIds || !Array.isArray(tableData.recordIds)) {
      throw new Error('Payload missing recordIds');
    }

    for (const recordId of tableData.recordIds) {
      // Fetch full record from Airtable
      const recordUrl = `https://api.airtable.com/v0/${p.baseId}/${p.tableId}/${recordId}`;
      const recordResponse = await fetchImpl(recordUrl, {
        headers: {
          Authorization: `Bearer ${config.airtablePersonalAccessToken}`,
        },
      });
      if (!recordResponse.ok) {
        throw new Error(
          `Airtable API error: ${recordResponse.status} ${recordResponse.statusText} for ${recordUrl}`
        );
      }
      const record: AirtableRecord = await recordResponse.json();

      if (!record.fields) throw new Error('Record missing fields');
      if (!record.createdTime) throw new Error('Record missing createdTime');

      // Build Discord embed fields
      const embedFields: Array<{ name: string; value: string; inline: boolean }> = [
        { name: 'Record ID', value: record.id, inline: true },
        { name: 'Created Time', value: record.createdTime, inline: true },
      ];

      for (const [fieldName, fieldValue] of Object.entries(record.fields)) {
        if (embedFields.length >= 25) break; // Discord limit
        embedFields.push({ name: fieldName, value: String(fieldValue), inline: true });
      }

      const embed = {
        title: 'New Record Created',
        description: 'A new record has been added to the table.',
        fields: embedFields,
        timestamp: record.createdTime,
      };

      const discordPayload = {
        content: record.id,
        embeds: [embed],
      };

      const discordResponse = await fetchImpl(config.discordWebhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(discordPayload),
      });
      if (!discordResponse.ok) {
        throw new Error(
          `Discord webhook error: ${discordResponse.status} ${discordResponse.statusText} for ${config.discordWebhookUrl}`
        );
      }
      const discordResult = await discordResponse.json();
      messageIds.push(discordResult.id);
    }
  }

  return { messageIds };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, AirtableWebhookPayload, HandleResult } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch: discordFetch, calls } = contractFetch();
    const fetch = async (input: RequestInfo, init?: RequestInit) => {
      const url = input instanceof Request ? input.url : String(input);
      if (url.includes('api.airtable.com')) {
        // Mock Airtable record fetch for the example record
        return jsonResponse({
          id: 'recAbCdEfGhIjKlMnO',
          fields: {},
          createdTime: '2023-04-10T12:34:56.000Z',
        });
      }
      return discordFetch(input, init);
    };

    const config: ConnectorConfig = {
      airtablePersonalAccessToken: 'test-token',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
      fetch,
    };

    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.messageIds).toEqual(['123456789012345678']);
  });
});

describe('handle', () => {
  const validConfig: ConnectorConfig = {
    airtablePersonalAccessToken: 'test-token',
    discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
  };

  it('happy path: fetches record and sends to Discord with correct mapping', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('api.airtable.com')) {
        return jsonResponse({
          id: 'rec123',
          fields: { Name: 'Test', Status: 'Active' },
          createdTime: '2024-01-01T00:00:00.000Z',
        });
      }
      if (req.url === validConfig.discordWebhookUrl) {
        return jsonResponse({ id: 'msg1', channel_id: 'ch1', content: 'rec123' }, 200);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'rec123',
          baseId: 'app123',
          tableId: 'tbl123',
          webhookId: 'whk123',
          timestamp: '2024-01-01T00:00:00.000Z',
          baseTransactionNumber: 1,
          changedTablesById: {
            tbl123: {
              recordIds: ['rec123'],
              cellValuesByFieldId: {},
              changedFieldsByRecordId: {},
            },
          },
        },
      ],
    };

    const result = await handle(payload, { ...validConfig, fetch });
    expect(result.messageIds).toEqual(['msg1']);

    // Verify Airtable fetch with bearer token
    const airtableCall = calls.find((c) => c.url.includes('api.airtable.com'));
    expect(airtableCall).toBeDefined();
    expect(airtableCall?.headers.get('authorization')).toBe('Bearer test-token');

    // Verify Discord payload
    const discordCall = calls.find((c) => c.url === validConfig.discordWebhookUrl);
    expect(discordCall).toBeDefined();
    expect(discordCall?.method).toBe('POST');
    const discordBody = discordCall?.json as {
      content: string;
      embeds: Array<{ fields: Array<{ name: string; value: string }> }>;
    };
    expect(discordBody.content).toBe('rec123');
    expect(discordBody.embeds[0].fields).toEqual(
      expect.arrayContaining([
        { name: 'Record ID', value: 'rec123', inline: true },
        { name: 'Created Time', value: '2024-01-01T00:00:00.000Z', inline: true },
        { name: 'Name', value: 'Test', inline: true },
        { name: 'Status', value: 'Active', inline: true },
      ])
    );
  });

  it('throws on missing required field (payloads)', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { payloads: null } as unknown as AirtableWebhookPayload;
    await expect(handle(payload, { ...validConfig, fetch })).rejects.toThrow(
      'Payload must contain a "payloads" array'
    );
  });

  it('throws on missing baseId in payload', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'rec1',
          baseId: '',
          tableId: 'tbl1',
          webhookId: 'whk1',
          timestamp: '2024-01-01T00:00:00.000Z',
          baseTransactionNumber: 1,
          changedTablesById: {
            tbl1: { recordIds: ['rec1'], cellValuesByFieldId: {}, changedFieldsByRecordId: {} },
          },
        },
      ],
    };
    await expect(handle(payload, { ...validConfig, fetch })).rejects.toThrow('Payload missing baseId');
  });

  it('throws on non-2xx Discord response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('api.airtable.com')) {
        return jsonResponse({
          id: 'rec1',
          fields: {},
          createdTime: '2024-01-01T00:00:00.000Z',
        });
      }
      return jsonResponse({ error: 'Unauthorized' }, 401);
    });

    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'rec1',
          baseId: 'app1',
          tableId: 'tbl1',
          webhookId: 'whk1',
          timestamp: '2024-01-01T00:00:00.000Z',
          baseTransactionNumber: 1,
          changedTablesById: {
            tbl1: { recordIds: ['rec1'], cellValuesByFieldId: {}, changedFieldsByRecordId: {} },
          },
        },
      ],
    };

    await expect(handle(payload, { ...validConfig, fetch })).rejects.toThrow(
      'Discord webhook error: 401 Unauthorized'
    );
    expect(calls.length).toBe(2); // Airtable + Discord
  });

  it('throws on non-2xx Airtable response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('api.airtable.com')) {
        return jsonResponse({ error: 'Not Found' }, 404);
      }
      return jsonResponse({}, 200);
    });

    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'rec1',
          baseId: 'app1',
          tableId: 'tbl1',
          webhookId: 'whk1',
          timestamp: '2024-01-01T00:00:00.000Z',
          baseTransactionNumber: 1,
          changedTablesById: {
            tbl1: { recordIds: ['rec1'], cellValuesByFieldId: {}, changedFieldsByRecordId: {} },
          },
        },
      ],
    };

    await expect(handle(payload, { ...validConfig, fetch })).rejects.toThrow(
      'Airtable API error: 404 Not Found'
    );
  });
});

# Airtable to Discord Webhook Connector

This connector receives an Airtable "new record" webhook payload, fetches the full record data from the Airtable REST API, and sends a formatted message to a Discord channel via an incoming webhook.

## What it does

1. Accepts the webhook payload delivered by Airtable when a new record is created (or via polling the `/payloads` endpoint).
2. For each record ID in the payload, calls the Airtable API to retrieve the complete record (including all field values and the creation timestamp).
3. Constructs a Discord webhook message containing:
   - `content`: the Airtable record ID.
   - `embeds`: a single embed with title "New Record Created", a description, and fields for every Airtable field (plus Record ID and Created Time).
   - `timestamp`: the record's `createdTime` (ISO 8601).
4. POSTs the message to the configured Discord webhook URL.
5. Returns the Discord message IDs for all successfully sent messages.

## Configuration

The connector requires the following configuration values (typically supplied via environment variables):

| Config property | Environment variable | Description |
|-----------------|----------------------|-------------|
| `airtablePersonalAccessToken` | `AIRTABLE_PERSONAL_ACCESS_TOKEN` | Airtable personal access token with permission to read the base/table. |
| `discordWebhookUrl` | `DISCORD_WEBHOOK_URL` | Full Discord incoming webhook URL (e.g. `https://discord.com/api/webhooks/{webhook.id}/{webhook.token}`). |
| `fetch` | (optional) | Custom `fetch` implementation (defaults to global `fetch`). Used for testing. |

## Usage example

```typescript
import { handle, ConnectorConfig, AirtableWebhookPayload } from './connector';

const config: ConnectorConfig = {
  airtablePersonalAccessToken: process.env.AIRTABLE_PERSONAL_ACCESS_TOKEN!,
  discordWebhookUrl: process.env.DISCORD_WEBHOOK_URL!,
};

// In your webhook handler (e.g. Express, Fastify, etc.):
app.post('/airtable-webhook', async (req, res) => {
  try {
    const payload = req.body as AirtableWebhookPayload;
    const result = await handle(payload, config);
    res.json({ success: true, messageIds: result.messageIds });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false, error: String(err) });
  }
});
```

## Assumptions

- The Airtable webhook payload follows the structure documented at https://community.airtable.com/other-questions-13/get-new-record-data-with-webhooks-18306 (i.e., it contains a `payloads` array with `changedTablesById` pointing to record IDs).
- The connector must call the Airtable REST API (`GET /v0/{baseId}/{tableId}/{recordId}`) to obtain the `fields` object and `createdTime` for each record.
- The Discord webhook URL already includes the webhook token in the path; no additional authentication headers are required.
- The Discord webhook accepts a JSON payload with at least `content` or `embeds` (we provide both).
- Embed field limits (25 fields per embed, 6000 total characters) are respected by truncating after 25 fields.
- The connector does not implement pagination or deduplication; it processes every record ID present in the incoming payload.
- Errors from either Airtable or Discord (non-2xx responses) are thrown as descriptive `Error` objects including the status code and endpoint.

